def(
    Set.injective(f@Set.ctxt.f),
    Logic.forall(
        list-partial(Type.judge(@x_1, S@Set.ctxt.S), Type.judge(@x_2, S@Set.ctxt.S)),
        Logic.implies(list-partial(
            Set.mem(x_1, Set.domain(f@Set.ctxt.f)),
            Set.mem(x_2, Set.domain(f@Set.ctxt.f)),
            Neq(x_1, x_2)
            ),
            Neq(Type.apply(f@Set.ctxt.f, x_1), Type.apply(f@Set.ctxt.f, x_2))
        )
    )
)
